window.MONSTER_CHUNK_5 = [{"name":"Catfolk","cr":0.5,"xp":200,"race":"Catfolk","classes":[{"class":"ranger","level":1}],"alignment":"NG","size":"Medium","type":"humanoid","subtypes":["catfolk"],"init":3,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex","hp":12,"hd":"1d10+2","hdvalue":1,"fort":3,"ref":5,"will":0,"speed":[{"type":"land","speed":30}],"melee":"longsword +3 (1d8+2/19-20)","ranged":"longbow +5 (1d8/3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"magical beasts +2"}],"strength":14,"dexterity":17,"constitution":12,"intelligence":8,"wisdom":11,"charisma":12,"baseatk":1,"cmb":3,"cmd":16,"feats":[{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Climb","value":5},{"skill":"Handle Animal","value":5},{"skill":"Knowledge (nature)","value":3},{"skill":"Perception","value":2},{"skill":"Stealth","value":8},{"skill":"Survival","value":6}],"languages":["Catfolk","Common"],"sq":[{"type":"cat's luck"},{"type":"sprinter"},{"type":"track","details":"+1"},{"type":"wild empathy","details":"+2"}],"environments":["any temperate forests","any temperate plains","any warm forests","any warm plains","any urban"],"organizations":["solitary","pair","pride (3-12 plus 1 leader of 3rd level and 1-4 cheetahs or leopards)","tribe (13-60 plus 50% noncombatants and 1 subchief of 3rd level per 10 adults, and 1 chief of 6th level plus 6-12 cheetahs or leopards)"],"treasure":"none","description_visual":"This lithe, catlike humanoid has a long tail and pointed ears. Her feline eyes sparkle with curiosity and mischief.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Cat's Luck","kind":"Ex","details":"Once per day when a catfolk makes a Reflex saving throw, it can roll the saving throw twice and take the better result. It must decide to use this ability before the saving throw is attempted."},{"type":"Sprinter","kind":"Ex","details":"A catfolk gains a 10-foot racial bonus to its speed when using the charge, run, or withdraw actions."}],"description":"Most catfolk are tribal hunter-gatherers who dwell in harmony with nature, though some tribes have acclimated well to urban environments. As a culture, catfolk are loyal, generous, and amiable. They like belonging to and being at harmony with a group whose members work together to accomplish their needs and wants. Tribal catfolk prefer for the most capable societal members to lead, so every tribe has a council of elevated subchiefs. A tribe's chief is usually the most competent (and magically talented) member of that tribe.\n\nPersonal growth is part of catfolk culture, as is expression as a means of personal exploration. Catfolk have few taboos, and often exhibit harmless but strange eccentricities. Individuals cultivate a wide range of pursuits and self-expression, taking risks others might label unwise. Most individual catfolk like to be the center of attention, but not at the cost of group cohesion.","as_character":[{"description":"Catfolk have no racial Hit Dice, gaining their capabilities from class levels. All catfolk have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, -2 Wisdom, +2 Charisma: Catfolk are agile and amiable, but they are known for their lack of common sense and self-control."},{"type":"Low-Light Vision","value":"In dim light, catfolk can see twice as far as humans."},{"type":"Cat's Luck","value":"See above."},{"type":"Sprinter","value":"See above."},{"type":"Natural Hunter","value":"Catfolk receive a +2 racial bonus on Perception, Stealth, and Survival checks."},{"type":"Languages","value":"Catfolk speak Catfolk and Common. A catfolk who has a high Intelligence score can choose from the following bonus languages: Elven, Gnoll, Gnome, Goblin, Halfling, Orc, and Sylvan."}]}],"ecology":"","habitat_society":"","gear":"studded leather armor, longbow with 20 arrows, longsword"},{"name":"Changeling","cr":0.5,"xp":200,"race":"Changeling","classes":[{"class":"witch","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","subtypes":["changeling"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":10,"ac_touch":9,"ac_flat_footed":10,"ac_mods":"-1 Dex, +1 natural","hp":5,"hd":"1d6+2","hdvalue":1,"fort":1,"ref":-1,"will":2,"speed":[{"type":"land","speed":30}],"melee":"quarterstaff (1d6) or 2 claws (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"cauldron"}],"spellsprepared_caster":"witch","spellsprepared_caster_level":1,"spellsprepared_concentration":6,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"hypnotism"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"light"},{"spell":"touch of fatigue"}]}],"strength":10,"dexterity":9,"constitution":12,"intelligence":17,"wisdom":10,"charisma":13,"baseatk":0,"cmb":0,"cmd":9,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Casting"}],"skills":[{"skill":"Craft (alchemy)","value":11},{"skill":"Heal","value":4},{"skill":"Knowledge (arcana)","value":7},{"skill":"Spellcraft","value":7},{"skill":"Use Magic Device","value":5}],"languages":["Common","Draconic","Dwarven","Elven"],"sq":[{"type":"hag trait","details":"green widow"},{"type":"witch's familiar","details":"spider"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard (quarterstaff)","description_visual":"This young woman has a slender frame and a beautiful face, yet there's something vaguely unnerving about her appearance. Her skin is unnaturally pale, her hair is dark, and each of her eyes is a different color.","source":"AP 43","description":"Born of mysterious origins and raised by unknowing foster parents, changelings are the children of hags and their tricked lovers. Most don't know of their monstrous origins, but there comes a time in every changeling's life when these roots begin to call out to their host, urging the confused girl toward some end she cannot identify. Changelings are always female, tall, and slender. A changeling's hair is typically dark and her skin abnormally pale, but she otherwise looks for all practical purposes like a member of her father's race. A frequent but not universal trait of changelings is their mismatched, different-colored eyes. Upon reaching puberty and adulthood, the average changeling stands approximately 5-1/2 ft. tall and weighs about 110 pounds. Ecology When a hag of any sort conceives a child with a man, the result is a changeling. The male parent is usually eaten or killed by his partner before he can see the offspring, or else flees the area in shame upon discovering the true nature of his lover, and the hag herself interacts with the child just long enough to set it on the stoop of some unsuspecting family or temple. Depending on the race of her father, a changeling can resemble any type of humanoid, including dwarves, gnomes, and even orcs and goblins. A changeling and her new family are never aware of the strange child's true parents, but in most cases everyone involved is keenly aware that there is something odd about the frail child with the ghostly pallor. Even the young girl herself can easily see that she possesses abilities others don't-powers that are subtle at younger ages and only truly begin to manifest themselves when she reaches adolescence. It is around puberty that the changeling begins to hear what hags refer to as \"the call,\" a hypnotic, spiritual voice that only she can hear and that beckons her to travel. To where, the changeling doesn't know, but the underlying prospect of finding out her true origins is often enough to drive the girl to seek out the source of this mystical voice. The voice is in fact that of the changeling's birth mother, who forms a coven with two others hags in order to summon her child back to her, now that she is old enough to fully transform into a hag. This transformative ritual is a barbaric one that only the most determined changelings willingly go through; upon arriving at the coven, it is usually too late to turn back for changelings who were merely drawn to the voice by curiosity. Those who seek power, however, identify with the hags, and happily go through the ordeal in order to unlock their dormant abilities. Regardless of her desires, though, a changeling who has undergone the transformation cannot go back; once she becomes a hag, she remains a hag, and her mind turns as wicked as her form has turned hideous. Changelings who ignore the call eventually cease to hear it. In this case, a hag mother sometimes disguises herself and ventures into civilization, seeking out her daughter. If she finds her, she lures the girl back to the coven, where she can perform the ritual of transformation. The process of performing the call or physically retrieving the changeling is taxing, though, and many hags find it easier to simply lure in another mate and birth another changeling in hopes that this one will heed the evertantalizing call. Habitat & Society Raised wherever she will be accepted, a changeling has no real say in the habitat she grows up in. Families who inadvertently raise changelings often react in one of two ways toward the strange child's development of supernatural powers: they either embrace the girl, nurturing her and her gift, or they disown her as an abomination, casting her out into a world of loneliness and resentment. Of course, this reaction to her power often has a huge inf luence over the changeling's course of action as a young adult. Changelings who are accepted by their adopted society often don't see the need to follow their mothers' voices, instead using their powers for their own ends, whereas shunned individuals almost always answer the call and become treacherous hags with embittered hearts and shattered souls. Hags usually prefer to mate with the prevalent and fecund humans of Golarion, producing changelings that resemble humans. Changelings of other races do occur, but their attitude and outlook are much more dependent on the attitudes of their adoptive parents than on their racial background. Changelings rarely band together with other changelings, as hags only seldom allow their unions to result in offspring, and changelings encountering others of their type may never recognize their shared origins. Thus, the abandoned offspring graft themselves into whatever society will accept them, adapting to new roles with remarkable ease. If a changeling chooses to heed the call that beckons her as a young woman, she quickly finds herself in an entirely different sort of society: hags, though accepting of their own brood, are quite unlike any other creatures, and their form of culture is so primitive and evil that it can hardly be called culture at all. A changeling turned hag follows the same patterns as her mother and other brethren, eventually charming an unwitting suitor and creating a changeling offspring of her own, repeating the vicious cycle. Having no innate predisposition toward evil, a changeling's values are solely a product of her environment, and any given individual is just as likely to perform evil as she is to act righteously. Often, though, a changeling's slightly unusual appearance marks her as the target for harassment, potentially leading her toward a vengeful path. Any means of releasing innate magical energy is good enough for the changeling, and many become witches.","as_character":[{"description":"Changelings are defined by their class levels-they don't possess racial Hit Dice. All changelings have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"-2 Constitution, +2 Wisdom, +2 Charisma: Changelings are frail, but possess a sharp wit and unnatural beauty."},{"type":"Hag Trait","value":"A changeling possesses one of the following traits, depending on the type of hag her mother is."},{"type":"Hulking Changeling","value":"A changeling who was born of an annis hag is much more physically formidable than other changelings. You receive a +1 trait bonus on any damage you inf lict with a melee attack."},{"type":"Green Widow","value":"A changeling of green hag descent is naturally able to lure in potential mates and effectively trick them into pursuing her. You gain a +2 trait bonus on Bluff checks made against characters that might be sexually attracted to you."},{"type":"Sea Lungs","value":"A changeling with a sea hag mother can survive underwater for longer than usual. You gain the ability to hold your breath for a number of rounds equal to three times your Constitution score instead of two."},{"type":"Claws","value":"A changeling's hands and fingernails tend to harden and become sharp as she reaches adolescence. This gives her the claw (1d4) natural attack."},{"type":"Natural Armor","value":"Hags and their offspring have uncommonly tough skin. A changeling begins play with a natural armor bonus of +1."},{"type":"Darkvision","value":"Changelings can see in the dark up to 60 ft."},{"type":"Languages","value":"Changelings begin play speaking the primary language of their host society and Common. Changelings who have high Intelligence scores can choose from among the following bonus languages: Aklo, Draconic, Dwarven, Elven, Giant, Gnoll, Goblin, and Orc."}]}],"ecology":"When a hag of any sort conceives a child with a man, the result is a changeling. The male parent is usually eaten or killed by his partner before he can see the offspring, or else flees the area in shame upon discovering the true nature of his lover, and the hag herself interacts with the child just long enough to set it on the stoop of some unsuspecting family or temple. Depending on the race of her father, a changeling can resemble any type of humanoid, including dwarves, gnomes, and even orcs and goblins. A changeling and her new family are never aware of the strange child's true parents, but in most cases everyone involved is keenly aware that there is something odd about the frail child with the ghostly pallor. Even the young girl herself can easily see that she possesses abilities others don't-powers that are subtle at younger ages and only truly begin to manifest themselves when she reaches adolescence. It is around puberty that the changeling begins to hear what hags refer to as \"the call,\" a hypnotic, spiritual voice that only she can hear and that beckons her to travel. To where, the changeling doesn't know, but the underlying prospect of finding out her true origins is often enough to drive the girl to seek out the source of this mystical voice. The voice is in fact that of the changeling's birth mother, who forms a coven with two others hags in order to summon her child back to her, now that she is old enough to fully transform into a hag. This transformative ritual is a barbaric one that only the most determined changelings willingly go through; upon arriving at the coven, it is usually too late to turn back for changelings who were merely drawn to the voice by curiosity. Those who seek power, however, identify with the hags, and happily go through the ordeal in order to unlock their dormant abilities. Regardless of her desires, though, a changeling who has undergone the transformation cannot go back; once she becomes a hag, she remains a hag, and her mind turns as wicked as her form has turned hideous. Changelings who ignore the call eventually cease to hear it. In this case, a hag mother sometimes disguises herself and ventures into civilization, seeking out her daughter. If she finds her, she lures the girl back to the coven, where she can perform the ritual of transformation. The process of performing the call or physically retrieving the changeling is taxing, though, and many hags find it easier to simply lure in another mate and birth another changeling in hopes that this one will heed the evertantalizing call.","habitat_society":"Raised wherever she will be accepted, a changeling has no real say in the habitat she grows up in. Families who inadvertently raise changelings often react in one of two ways toward the strange child's development of supernatural powers: they either embrace the girl, nurturing her and her gift, or they disown her as an abomination, casting her out into a world of loneliness and resentment. Of course, this reaction to her power often has a huge inf luence over the changeling's course of action as a young adult. Changelings who are accepted by their adopted society often don't see the need to follow their mothers' voices, instead using their powers for their own ends, whereas shunned individuals almost always answer the call and become treacherous hags with embittered hearts and shattered souls. Hags usually prefer to mate with the prevalent and fecund humans of Golarion, producing changelings that resemble humans. Changelings of other races do occur, but their attitude and outlook are much more dependent on the attitudes of their adoptive parents than on their racial background. Changelings rarely band together with other changelings, as hags only seldom allow their unions to result in offspring, and changelings encountering others of their type may never recognize their shared origins. Thus, the abandoned offspring graft themselves into whatever society will accept them, adapting to new roles with remarkable ease. If a changeling chooses to heed the call that beckons her as a young woman, she quickly finds herself in an entirely different sort of society: hags, though accepting of their own brood, are quite unlike any other creatures, and their form of culture is so primitive and evil that it can hardly be called culture at all. A changeling turned hag follows the same patterns as her mother and other brethren, eventually charming an unwitting suitor and creating a changeling offspring of her own, repeating the vicious cycle. Having no innate predisposition toward evil, a changeling's values are solely a product of her environment, and any given individual is just as likely to perform evil as she is to act righteously. Often, though, a changeling's slightly unusual appearance marks her as the target for harassment, potentially leading her toward a vengeful path. Any means of releasing innate magical energy is good enough for the changeling, and many become witches. Changeling Characters Changelings are defined by their class levels-they don't possess racial Hit Dice. All changelings have the following racial traits. -2 Constitution, +2 Wisdom, +2 Charisma: Changelings are frail, but possess a sharp wit and unnatural beauty. Hag Trait: A changeling possesses one of the following traits, depending on the type of hag her mother is. Hulking Changeling: A changeling who was born of an annis hag is much more physically formidable than other changelings. You receive a +1 trait bonus on any damage you inf lict with a melee attack. Green Widow: A changeling of green hag descent is naturally able to lure in potential mates and effectively trick them into pursuing her. You gain a +2 trait bonus on Bluff checks made against characters that might be sexually attracted to you. Sea Lungs: A changeling with a sea hag mother can survive underwater for longer than usual. You gain the ability to hold your breath for a number of rounds equal to three times your Constitution score instead of two. Claws: A changeling's hands and fingernails tend to harden and become sharp as she reaches adolescence. This gives her the claw (1d4) natural attack. Natural Armor: Hags and their offspring have uncommonly tough skin. A changeling begins play with a natural armor bonus of +1. Darkvision: Changelings can see in the dark up to 60 ft. Languages: Changelings begin play speaking the primary language of their host society and Common. Changelings who have high Intelligence scores can choose from among the following bonus languages: Aklo, Draconic, Dwarven, Elven, Giant, Gnoll, Goblin, and Orc.","gear":"quarterstaff"},{"name":"Changeling","cr":0.5,"xp":200,"race":"Changeling","classes":[{"class":"witch","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","subtypes":["changeling"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":10,"ac_touch":9,"ac_flat_footed":10,"ac_mods":"-1 Dex, +1 natural","hp":8,"hd":"1d6+2","hdvalue":1,"fort":1,"ref":-1,"will":4,"speed":[{"type":"land","speed":30}],"melee":"2 claws +0 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"cauldron"}],"spellsprepared_caster":"witch","spellsprepared_caster_level":1,"spellsprepared_concentration":6,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"hypnotism"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"light"},{"spell":"touch of fatigue"}]}],"strength":10,"dexterity":8,"constitution":12,"intelligence":15,"wisdom":14,"charisma":15,"baseatk":0,"cmb":0,"cmd":9,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Casting"}],"skills":[{"skill":"Craft (alchemy)","value":10},{"skill":"Heal","value":6},{"skill":"Knowledge (arcana)","value":6},{"skill":"Spellcraft","value":6}],"languages":["Common","Draconic","Elven","Orc"],"sq":[{"type":"hulking changeling"},{"type":"witch's familiar","details":"spider"}],"environments":["any"],"organizations":["solitary"],"treasure":"gear (quarterstaff, spell component pouch)","description_visual":"This slender woman's skin is unnaturally pale, her hair is dark, and each of her eyes is a different color.","source":"PFRPG Bestiary 4","description":"Born of mysterious origins and raised by unknowing foster parents, changelings are the children of hags and their tricked lovers. Most don't know of their monstrous origins, but there comes a time in every changeling's life when these roots begin to call out to their host, urging the confused girl toward some end she can't identify. When a hag of any sort conceives a child with a man, the result is a changeling. The male parent is usually killed and eaten by his partner before he can see the offspring. Changelings are, without exception, female, and almost always tall and slender. A changeling's hair is typically long and dark, and her skin abnormally pale, but she otherwise looks for all practical purposes like a member of her father's race. A frequent-but not universal-trait of changelings isn'ticeably mismatched eyes, each of which is a different color common among her father's race. Upon reaching puberty and adulthood, the average changeling born to a human father stands approximately 5-1/2 ft. tall and weighs about 110 pounds.","as_character":[{"description":"Changelings are defined by their class levels; they don't have racial Hit Dice. All changelings have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"-2 Constitution, +2 Wisdom, +2 Charisma: Changelings are frail, but are clever and comely."},{"type":"Hag Trait","value":"A changeling possesses one of the following traits, depending on the type of hag her mother is."},{"type":"Hulking Changeling (Annis Hag)","value":"The changeling gains a +1 racial bonus on melee damage rolls."},{"type":"Green Widow (Green Hag)","value":"The changeling gains a +2 racial bonus on Bluff checks against creatures that are sexually attracted to her."},{"type":"Sea Lungs (Sea Hag)","value":"The changeling can hold her breath for a number of rounds equal to 3 x her Constitution score before she risks drowning."},{"type":"Claws","value":"A changeling's hands and fingernails tend to harden and become sharp, granting her two claw attacks, each of which deals 1d4 points of damage."},{"type":"Natural Armor","value":"Changelings have a +1 natural armor bonus."},{"type":"Darkvision","value":"Changelings can see in the dark up to 60 ft."},{"type":"Languages","value":"Changelings begin play speaking Common and the primary language of their host society. Changelings who have high Intelligence scores can choose from the following: Aklo, Draconic, Dwarven, Elven, Giant, Gnoll, Goblin, and Orc."}]}],"ecology":"","habitat_society":""},{"name":"Chon Chon","cr":0.5,"xp":200,"alignment":"CN","size":"Tiny","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["jabber (15 ft., DC 11)"],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":9,"hd":"2d8","hdvalue":2,"fort":0,"ref":4,"will":4,"speed":[{"type":"land","speed":10},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +1 (1d3-2)","ranged":"acid spit +5 (1d4 acid)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]}],"strength":6,"dexterity":15,"constitution":10,"intelligence":7,"wisdom":12,"charisma":13,"baseatk":1,"cmb":1,"cmd":9,"feats":[{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Fly","value":15},{"skill":"Perception","value":6,"special":"+10 to listen"}],"languages":["Common"],"environments":["temperate forests","temperate ruins","tropical forests","tropical ruins"],"organizations":["solitary","pair","flight (3-12)"],"treasure":"none","description_visual":"This flying head has incredibly large ears that constantly flap to keep the creature aloft. It babbles to itself as it flies, as if to remind itself of secrets only it knows.","source":"AP 53","special_abilities":[{"type":"Acid Spit","kind":"Ex","details":"A chon chon can spit a disgusting blob of acid at a single foe, making a ranged attack with a range of 30 ft. and no range increment. A successful attack deals 1d4 points of acid damage and forces the target to make a DC 11 Fortitude saving throw to avoid becoming nauseated for 1 round. The save DC is Constitution-based."},{"type":"Jabber","kind":"Su","details":"A chon chon endlessly mutters half-remembered spells and meaningless arcane formulae to itself. This jabbering creates a kind of magical static that interferes with spells being cast nearby. Any creature attempting to cast a spell within 15 ft. of a chon chon must make a successful DC 11 concentration check or lose the spell. This is a sonic, mind-affecting effect. The concentration DC is Charisma-based."}],"description":"Chon chons appear to be human heads with ears so grotesquely enlarged that they can serve as fleshy wings. Their jealous hatred of all beings with full bodies easily counters their comical appearance, however. Accursed creatures drawn to places of dark magic and arcane disasters, chon chons possess the desires of the most obsessed magic users, but their dementia and twisted forms prevent them from ever obtaining the power they seek. Although these crazed beings loathe all things, they do find a vicious kind of solace among their own kind, not out of any sort of commiseration, but rather by wallowing in the pain of their own kind. Such hateful swarms gather to bear witness to each others' misery, inadvertently increasing the deadly efficacy of the entire group.\n\nA single chon chon is no larger than a human head and weighs 10 pounds at most. The creature's ears give\n\nit a total wingspan of 3 ft., making it appear much larger and more menacing.\n\nEcology\n\nA chon chon's winglike ears endlessly flap, serving as monstrous wings that give it surprising grace in flight. These creatures always seem distracted, carrying on perpetual one-sided conversations and listening to voices only they can hear, then replying aloud with magical recitations or snippets of botched arcane formulae in a gibberish amalgam of Common, Draconic, and meaningless noises. This blathering has no meaning, mundane or arcane, but sounds so similar to the common phrases and syllables of magic that it insidiously intrudes upon the minds of spellcasters working their craft, invading their thoughts like an arcane earworm. An individual chon chon can suppress this babbling to speak semi-intelligibly-as much as such an insanely erratic creature can be called intelligible-but rarely does so for more than a minute before lapsing back into nonsense. Groups of chon chons seem to have no ability to quiet themselves, being little more than a collection of raving lunatics inspiring one another to ever-greater heights of insanity.\n\nAlthough chon chons appear to be disembodied human heads, they are a unique race of creatures and not merely the victims of a magical curse-though some particularly demented spellcasters have discovered methods by which they might take the forms of these creatures to horrific effect.\n\nHow chon chons increase their numbers few scholars know-and far fewer care to find out. Hateful of all things, including others of their kinds, to say nothing of their lack of generative organs, they seem doomed to extinction. Many assume these terrors spread their terrible condition in a way similar to that of vargouilles, which many mistake them for at first glance. Chon chons, however, lack those outsiders' terrifying kiss. Beyond general appearance, few similarities exist between these two races.\n\nSecret of the Kalkus\n\nCertain nefarious sorcerers-known in some lands as kalkus-seek to mimic the horrifying shape and strange abilities of chon chons, or aff lict their foes with such a curse. To this end, they've created a terrifying draught with the power to transform the drinker into a being resembling a chon chon, though few can guess for how long.","ecology":"A chon chon's winglike ears endlessly flap, serving as monstrous wings that give it surprising grace in flight. These creatures always seem distracted, carrying on perpetual one-sided conversations and listening to voices only they can hear, then replying aloud with magical recitations or snippets of botched arcane formulae in a gibberish amalgam of Common, Draconic, and meaningless noises. This blathering has no meaning, mundane or arcane, but sounds so similar to the common phrases and syllables of magic that it insidiously intrudes upon the minds of spellcasters working their craft, invading their thoughts like an arcane earworm. An individual chon chon can suppress this babbling to speak semi-intelligibly-as much as such an insanely erratic creature can be called intelligible-but rarely does so for more than a minute before lapsing back into nonsense. Groups of chon chons seem to have no ability to quiet themselves, being little more than a collection of raving lunatics inspiring one another to ever-greater heights of insanity.\n\nAlthough chon chons appear to be disembodied human heads, they are a unique race of creatures and not merely the victims of a magical curse-though some particularly demented spellcasters have discovered methods by which they might take the forms of these creatures to horrific effect.\n\nHow chon chons increase their numbers few scholars know-and far fewer care to find out. Hateful of all things, including others of their kinds, to say nothing of their lack of generative organs, they seem doomed to extinction. Many assume these terrors spread their terrible condition in a way similar to that of vargouilles, which many mistake them for at first glance. Chon chons, however, lack those outsiders' terrifying kiss. Beyond general appearance, few similarities exist between these two races.\n\nSecret of the Kalkus\n\nCertain nefarious sorcerers-known in some lands as kalkus-seek to mimic the horrifying shape and strange abilities of chon chons, or aff lict their foes with such a curse. To this end, they've created a terrifying draught with the power to transform the drinker into a being resembling a chon chon, though few can guess for how long.","habitat_society":""},{"name":"Clockwork Spy","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"construct","subtypes":["clockwork"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 dodge, +2 size","hp":5,"hd":"1d10","hdvalue":1,"fort":0,"ref":3,"will":0,"immunities":["construct traits"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"clumsy"}],"melee":"slam +3 (1d2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"record audio"},{"type":"self-destruct"}],"strength":10,"dexterity":13,"wisdom":11,"charisma":1,"baseatk":1,"cmb":0,"cmd":12,"cmd_special":"+8 vs. trip","feats":[{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"}],"skills":[{"skill":"Climb","value":3},{"skill":"Fly","value":-3},{"skill":"Stealth","value":11}],"sq":[{"type":"swift reactions"},{"type":"winding"}],"environments":["any"],"organizations":["solitary"],"treasure":"incidental (gemstone worth 50 gp)","description_visual":"This tiny steel creature has one oversized eye, a spherical body, and several spiderlike legs of grinding metal.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Record Audio","kind":"Su","details":"A clockwork spy can record nearby sounds as a swift action, archiving all sound within a 20-foot spread onto a small gemstone worth 50 gp embedded in its body. The clockwork spy can record up to 1 hour of sound per Hit Die it possesses. Starting and stopping playback of recorded sound is a swift action. Removing a gemstone or installing a gemstone into a clockwork spy requires a DC 25 Disable Device check as a full-round action-failure doesn't damage the gemstone but does erase any recorded sounds on the gemstone. Since clockwork spies are not intelligent, they must be given simple commands as to when they are to start recording sounds. A clockwork spy can differentiate between creature types and subtypes, but not between specific individuals-a spy can be ordered to start recording sound as soon as a humanoid (human) or an aberration comes in range, but it cannot be ordered to start recording when a specific person comes within range. Once a clockwork spy begins recording sound, it cannot cease recording early. Likewise, it cannot record sound onto a gemstone that already contains a recording."},{"type":"Self-Destruct","kind":"Su","details":"Unless specifically programmed otherwise by its creator, a clockwork spy explodes 1 round after it is destroyed. During this round, the thing shrieks and thrashes about as if undergoing convulsions. On what would normally have been the clockwork spy's next action, it explodes, dealing 1d6 points of fire damage in a 5-foot radius (Reflex DC 10 half). A DC 20 Disable Device check made as a standard action can halt the spy's self-destruct sequence, but doesn't prevent it from dying. A clockwork spy that self-destructs automatically destroys its gemstone, along with any information contained inside it. The save DC is Constitution-based."}],"description":"These spindly and discreet mechanical arachnids are ideal for surveillance and reconnaissance missions, and can be vital tools in political intrigues or illicit consortium tactics. Their retractable, insectile wings make the swift creatures even craftier foes than most would anticipate. As they are less combat-oriented than many other clockworks, if a clockwork spy is caught in the act of recording its target, escape is usually the most practical course of action for it.\n\nClockwork spies are about 2 ft. wide from leg to leg, and weigh less than 40 pounds.\n\nConstruction\n\nThese delicate constructs are full of small parts and difficult to construct. The creator must start with crafted clockwork pieces worth 250 gp.\n\nCLOCKWORK SPY\n\nCL 12th; Price 1,250 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest and ghost sound, creator must be at least caster level 12th; Skill Craft (clockwork) DC 20; Cost 750 gp","ecology":"","habitat_society":""},{"name":"Compsognathus","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":6,"hd":"1d8+2","hdvalue":1,"fort":4,"ref":4,"will":0,"speed":[{"type":"land","speed":40},{"type":"swim","speed":20}],"melee":"bite +1 (1d3-1 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","strength":8,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":11,"charisma":5,"baseatk":0,"cmb":0,"cmd":9,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":4},{"skill":"Swim","value":10}],"environments":["temperate forests","temperate plains","warm forests","warm plains"],"organizations":["solitary","pair","pack (5-20)"],"treasure":"none","description_visual":"This small reptile has a snake-like neck and head, a bird-like body with strong legs for running, and a whip-like tail.","group":"Dinosaur","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 12; frequency 1/round for 4 rounds; effect 1d2 Str; cure 1 save."}],"description":"The compsognathus is a small dinosaur that moves in swift, darting motions. Its bite injects a venom that causes numbness and weakness, a trait that the animal uses to bring down larger prey. A compsognathus measures 3 ft. long and weighs 15 pounds.\n\nThese dinosaurs can serve spellcasters as a familiar. A compsognathus familiar grants its master a +4 bonus on Initiative checks.","ecology":"","habitat_society":""},{"name":"Crawling Hand","cr":0.5,"xp":200,"alignment":"NE","size":"Diminutive","type":"undead","init":0,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 size","hp":9,"hd":"1d8+5","hdvalue":1,"fort":2,"ref":0,"will":2,"immunities":["undead traits"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"claw +5 (1d1+1 plus grab)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"mark quarry"},{"type":"strangle"}],"strength":13,"dexterity":11,"intelligence":2,"wisdom":11,"charisma":14,"baseatk":0,"cmb":-4,"cmb_special":"+4 vs. grapple","cmd":7,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":4},{"skill":"Stealth","value":12},{"skill":"Survival","value":4}],"languages":["Common (can't speak)"],"environments":["any land"],"organizations":["solitary","gang (2-5)"],"treasure":"none","description_visual":"With a jolt, this severed hand springs to life, its fingers propelling it forth at great speed like a deformed spider.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Grab","kind":"Ex","details":"A crawling hand can use its grab ability on a creature of up to Medium size."}],"description":"Some say the origins of the crawling hand lie in the experiments of demented necromancers contracted to construct tiny assassins. Other tales tell of gruesome prosthetics sparked to life by evil magic, which then developed primitive sentience and vengefully strangled their hosts. Regardless, the crawling hand is an efficient killing tool.\n\nWhen not commanded to kill, the crawling hand remains still and can be handled and transported safely.\n\nTypically, owners carry them about in small, velvet-lined boxes. Crawling hands can also be placed as guardians and programmed with contingency commands, such as to hunt down and slay an individual who performs a specific task like violating a shrine, opening a warded door, or breaking the seal of a casket.","ecology":"","habitat_society":""},{"name":"Dhampir","cr":0.5,"xp":200,"race":"Dhampir","classes":[{"class":"fighter","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["dhampir"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex","hp":13,"hd":"1d10+3","hdvalue":1,"fort":2,"ref":3,"will":-4,"save_mods":"+2 vs. disease and mind-affecting effects","defensive_abilities":["negative energy affinity","resist level drain"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30}],"melee":"rapier +4 (1d6+1/18-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"detect undead"}]}],"strength":13,"dexterity":17,"constitution":10,"intelligence":10,"wisdom":8,"charisma":16,"baseatk":1,"cmb":5,"cmd":15,"cmd_special":"can't be tripped","feats":[{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Intimidate","value":7},{"skill":"Perception","value":1},{"skill":"Ride","value":5},{"skill":"Survival","value":3}],"languages":["Common"],"environments":["any land"],"organizations":["solitary","pair","court (3-8 and 1 vampire)"],"treasure":"none","description_visual":"This unnaturally graceful man moves without a sound, his gaze just as piercing as the needle-sharp blade he effortlessly wields.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Resist Level Drain","kind":"Ex","details":"A dhampir takes no penalties from energy draining effects, though he can still be killed if he accrues more negative levels then he has Hit Dice. After 24 hours, any negative levels a dhampir takes are removed without the need for an additional saving throw."}],"description":"Cursed from birth, dhampirs result from the rare and unnatural union of vampires and humans. Although not driven to consume blood for survival as their undead progenitors are, dhampirs nonetheless know a lifelong desire for blood that nothing else can truly sate. Those who survive their early years face a life of fear and mistrust, their unnatural beauty and incredible ref lexes marking them as scions of the night just as surely as their sensitivity to light. Although polluted by undeath, dhampirs do grow old and die, aging at a rate similar to elves.","as_character":[{"description":"Dhampirs are defined by class levels-they don't possess racial Hit Dice. All dhampirs have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Charisma, -2 Wisdom: Dhampirs are fast and seductive, but closer to death than most mortals."},{"type":"Senses","value":"Low-light vision and darkvision 60 ft."},{"type":"Manipulative","value":"+2 racial bonus on Bluff and Perception."},{"type":"Undead Resistance","value":"Dhampirs gain a +2 racial bonus on saving throws against disease and mind-affecting effects."},{"type":"Light Sensitivity","value":"See universal monster rules."},{"type":"Negative Energy Affinity","value":"See universal monster rules."},{"type":"Spell-Like Ability","value":"A dhampir can use detect undead three times per day as a spell-like ability. The caster level for this ability equals the dhampir's class level."},{"type":"Resist Level Drain","value":"See above."},{"type":"Languages","value":"Dhampirs begin play speaking Common. Those with high Intelligence can choose any language as a bonus language (except druidic and other secret languages)."}]}],"ecology":"","habitat_society":"","gear":"chain shirt, rapier"},{"name":"Dolphin","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":5,"will":5,"speed":[{"type":"swim","speed":80}],"melee":"slam +3 (1d4+1)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"constitution":13,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":1,"cmb":2,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":9},{"skill":"Swim","value":13}],"sq":[{"type":"hold breath"}],"environments":["any oceans"],"organizations":["solitary","pair","pod (3-18)"],"treasure":"none","description_visual":"This streamlined, fish-like mammal has sparkling eyes over a smiling mouth filled with hundreds of teeth.","source":"PFRPG Bestiary","special_abilities":[{"type":"Hold Breath","kind":"Ex","details":"A dolphin can hold its breath for a number of minutes equal to 6 times its Constitution score before it risks drowning."}],"description":"Dolphins are social predators that hunt shallow seas and rivers in large family groups called pods. Sailors are fond of dolphins and frequently tell tales of dolphins saving drowning fishermen or killing sharks with blows from their powerful snouts.","ecology":"","habitat_society":""},{"name":"Eagle","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":4,"will":2,"speed":[{"type":"land","speed":10},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"2 talons +3 (1d4), bite +3 (1d4)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":15,"charisma":7,"baseatk":0,"cmb":-1,"cmd":11,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":10}],"environments":["temperate mountains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This magnificent bird of prey has dark feathers save for those on its head, which are pure white.","source":"PFRPG Bestiary","description":"Among the most majestic of raptors, these predatory birds pluck fish from streams and lakes, drop down on rodents and small mammals in alpine meadows, and have even been known to pull young mountain goats from the assumed safety of their cliffs.\n\nThese creatures, like all birds of prey, have powerful clawed talons and sharp, hooked beaks perfect for tearing flesh. Their enhanced eyesight allows them to spot prey from great distances, and they typically hunt in wide circling patterns high above the ground.\n\nEagles typically build their massive nests in the tops of tall trees or among the rocky crags of steep cliffs. During breeding season, an eagle lays two eggs, but only one chick normally survives, as the stronger of the two usually kills and eats the weaker.\n\nEagles generally weigh between 8 and 15 pounds, with a wingspan of up to 7 ft., depending on the species.","ecology":"","habitat_society":""},{"name":"Ectoplasmic Human","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":7,"hd":"1d8+3","hdvalue":1,"fort":0,"ref":0,"will":2,"dr":"5/slashing","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"speed_mod":"air walk","melee":"slam +3 (1d4+3 plus horrifying ooze)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"horrifying ooze"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"}]}],"strength":16,"dexterity":11,"wisdom":10,"charisma":12,"baseatk":0,"cmb":3,"cmd":13,"feats":[{"feat":"Toughness","type":"bonus"}],"sq":[{"type":"phase lurch"}],"environments":["any"],"organizations":["solitary","pair","haunt (3-6)"],"treasure":"none","description_visual":"This slimy, shifting mass has the shape of a humanoid, but is made out of what appears to be some form of sticky rope or cloth.","group":"Ectoplasmic Creature","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Horrifying Ooze","kind":"Su","details":"Any creature struck by an ectoplasmic creature's slam attack must succeed at a DC 11 Will save or be shaken for 1d4 rounds. The save DC is Charisma-based."},{"type":"Phase Lurch","kind":"Su","details":"An ectoplasmic creature has the ability to pass through walls or material obstacles. To use this ability, the ectoplasmic creature must begin and end its turn outside of whatever wall or obstacle it's moving through. An ectoplasmic creature cannot move through corporeal creatures with this ability, and its movement speed is halved while moving through a wall or obstacle. Any surface it moves through is coated with a thin, silvery mucus that lingers for 1 minute."}],"description":"Drawn from energies of the Ethereal Plane, ectoplasm is a vile substance resembling thick tangles of slimy linen or dripping goo. It shapes itself into the form of an undead creature, creating a host for a soul unfortunate enough to be confined within it. The existence of an ectoplasmic being is a cruel one, and few souls willingly choose this painful form of undeath. An ectoplasmic creature is approximately the same size as the body it inhabited in life, though it weighs nearly twice as much, as the ropes of undead matter that compose its body are signif icantly heavier than most living flesh. Even more so than most undead beings, creatures born of ectoplasm live hateful existences, filled with nothing but a lust for destruction and suffering. They have no bodily needs and require no sustenance; the only thing an ectoplasmic creature feeds upon is its own hatred of the living. Once a spirit has passed to the afterlife, it seldom wishes to return at all, let alone in a disfigured ectoplasmic body. Spirits that aren't powerful enough to come back as ghosts or spectres sometimes return as ectoplasmic monsters, particularly when there are no remains of the creature's original body for its soul to inhabit in the form of a skeleton or zombie. Sometimes, ghosts and other strong undead purposefully draw upon ectoplasm from the ethereal realm, yearning for even more power in their ectoplasmic hosts. Those who suffer this sorrowful fate, by misfortune or choice, are usually stuck in their ectoplasmic prisons until death grants them sweet release from this unlife. The transition from death to ectoplasmic undeath is a torturous ordeal, as is retaining the horrid form into which the creature is reborn. Often, this persistent agony drives these beings beyond mad, creating within an insatiable rage akin to that experienced by frustrated ghosts and other haunted souls. An ectoplasmic creature's burning desperation and embitterment often pushes it toward violence: most such beings fling themselves into battle willingly, killing to satiate their natural hunger for the suffering of others, while simultaneously hoping to be killed and thus freed of their own suffering own. Whenever in contact with surfaces (including walls they pass through), ectoplasmic creatures leave a trail of a silvery substance that resembles a slug's mucus-a trait almost exclusive to these undead. This slippery secretion dries within moments, so if its encountered, there is surely such a creature lurking nearby. Ectoplasmic beings can inhabit any location, regardless of environment or climate. The horrors tend to prowl the areas in which they died, and rarely venture outside these areas, as though they were anchored there. Though these entities rarely coordinate complicated actions with others of their kind, they seem to do so unintentionally at times. Their unnatural strength makes ectoplasmic creatures formidable combatants, which those not familiar with fighting ectoplasmic creatures would expect by looking at them. Fortunately for the wary, the sticky ectoplasm that trails behind these undead monsters is a clear indicator of their presence, and most experienced clerics can identify the substance at a glance.","ecology":"","habitat_society":""},{"name":"Elf","cr":0.5,"xp":200,"race":"Elf","classes":[{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["elf"],"init":3,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex, +1 dodge","hp":8,"hd":"1d8","hdvalue":1,"fort":1,"ref":5,"will":1,"save_mods":"+2 vs. enchantments","speed":[{"type":"land","speed":30}],"melee":"rapier +1 (1d6+1/18-20)","ranged":"dagger +3 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":17,"constitution":12,"intelligence":10,"wisdom":13,"charisma":10,"baseatk":0,"cmb":1,"cmd":15,"feats":[{"feat":"Dodge"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Bluff","value":4},{"skill":"Climb","value":5},{"skill":"Disable Device","value":7},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":7},{"skill":"Swim","value":5}],"sq":[{"type":"sneak attack","details":"+1d6"},{"type":"trapfinding","details":"+1"}],"environments":["any land"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"Possessing a graceful, slender physique that is accentuated by long, pointed ears.","source":"Core Rulebook","description":"Generally taller than humans, elves possess a graceful, slender physique that is accentuated by their long, pointed ears.","as_character":[{"description":"Elves are defined by their class levels-they don't possess racial HD. They have the following racial traits.\n\n•","racial_traits":[{"type":"Ability Score Racial Traits","value":"Elves are nimble, both in body and mind, but their form is frail. They gain +2 Dexterity, +2 Intelligence, and -2 Constitution.\n\n•"},{"type":"Size","value":"Elves are Medium creatures and thus receive no bonuses or penalties due to their size.\n\n•"},{"type":"Type","value":"Elves are Humanoids with the elf subtype.\n\n•"},{"type":"Base Speed","value":"Elves have a base speed of 30 ft.\n\n•"},{"type":"Languages","value":"Elves begin play speaking Common and Elven. Elves with high Intelligence scores can choose from the following: Celestial, Draconic, Gnoll, Gnome, Goblin, Orc, and Sylvan. See the Linguistics skill for more information about these languages.\n\n•"},{"type":"Elven Immunities","value":"Elves are immune to magic sleep effects and gain a +2 racial saving throw bonus against enchantment spells and effects.\n\n•"},{"type":"Keen Senses","value":"Elves receive a +2 racial bonus on Perception checks.\n\n•"},{"type":"Elven Magic","value":"Elves receive a +2 racial bonus on caster level checks made to overcome spell resistance. In addition, elves receive a +2 racial bonus on Spellcraft skill checks made to identify the properties of magic items.\n\n•"},{"type":"Weapon Familiarity","value":"Elves are proficient with longbows (including composite longbows), longswords, rapiers, and shortbows (including composite shortbows), and treat any weapon with the word \"elven\" in its name as a martial weapon.\n\n•"},{"type":"Low-Light Vision","value":"Elves can see twice as far as humans in conditions of dim light."}]}],"ecology":"","habitat_society":"","gear":"leather armor, rapier, daggers (12), backpack, grappling hook, hooded lantern, oil (5), rations (3), silk rope, thieves' tools, 25 gp"},{"name":"Ermine","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":1,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +4 (1d3-4 plus attach)","space":"2-1/2 ft.","reach":"0 ft.","strength":3,"dexterity":15,"constitution":10,"intelligence":2,"wisdom":12,"charisma":5,"baseatk":0,"cmb":0,"cmd":6,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":10},{"skill":"Escape Artist","value":3},{"skill":"Stealth","value":14}],"environments":["temperate hills"],"organizations":["solitary"],"treasure":"none","description_visual":"Presented on these pages are base animal statistics for six additional familiars beyond those most commonly used by spellcasters-of course, these statistics can also be used for normal animals as well. These familiars utilize all the standard rules for familiars. Tiny or smaller familiars in this section use Dexterity to modify Climb and Swim skill checks.","group":"Familiar","source":"Reign Of Winter Player's Guide","special_abilities":[{"type":"Attach","kind":"Ex","details":"When a weasel hits with a bite attack, it automatically grapples its foe, inflicting automatic bite damage each round."}],"description":"While an ermine is a type of weasel, this specimen has white fur that allows it to blend into snowy surroundings. An ermine receives a +4 racial bonus on Stealth checks attempted while in snow.","ecology":"","habitat_society":""},{"name":"Exoskeleton Giant Cockroach","cr":0.5,"xp":200,"alignment":"NE","size":"Small","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":13,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+1 Dex, +1 natural, +1 size","hp":12,"hd":"2d8+3","hdvalue":2,"fort":0,"ref":1,"will":3,"dr":"5/bludgeoning","immunities":["undead traits"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":40,"maneuverability":"clumsy"}],"melee":"bite +3 (1d4+1)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":12,"wisdom":10,"charisma":10,"baseatk":1,"cmb":1,"cmd":12,"cmd_special":"+8 vs. trip","feats":[{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Climb","value":9},{"skill":"Fly","value":-5}],"sq":[{"type":"burst","details":"DC 11"}],"treasure":"none","description_visual":"The tattered remains of a dead stag beetle rumble to life, creaking and clattering forward on dry, brittle legs.","group":"Exoskeleton","source":"AP 91","description":"Found skittering through forgotten tombs, crawling through deep forests, and filling damp caverns, exoskeletons are animated carapaces of arthropods and other vermin. Most exoskeletons are the intentional creations of necromancers, but some of these undead monstrosities arise spontaneously from places awash with negative energy or are created by malfunctioning artifacts. Even though exoskeletons are just as mindless as they were when they were living, they now attack all living creatures on sight, exploding in a burst of dusty remains when they are destroyed.\n\nA spellcaster can create an exoskeleton using animate dead. An exoskeleton can be created from a mostly intact dead vermin that has an exoskeleton. This includes arachnids, insects, crustaceans, and even some mollusks, but not soft-bodied vermin such as jellyfish and leeches.","ecology":"","habitat_society":""},{"name":"Fast Zombie","cr":0.5,"xp":200,"alignment":"NE","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":12,"hd":"2d8+3","hdvalue":2,"fort":0,"ref":2,"will":3,"immunities":["undead traits"],"speed":[{"type":"land","speed":40}],"melee":"2 slams +4 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"quick strikes"}],"strength":17,"dexterity":14,"wisdom":10,"charisma":10,"baseatk":1,"cmb":4,"cmd":16,"feats":[{"feat":"Toughness","type":"bonus"}],"environments":["any"],"organizations":["any"],"treasure":"none","description_visual":"This walking corpse wears only a few soiled rags, its flesh rotting off its bones as it stumbles forward with unnatural quickness, arms outstretched.","group":"Zombie","source":"PFRPG Bestiary","special_abilities":[{"type":"Quick Strikes","kind":"Ex","details":"Whenever a fast zombie takes a full-attack action, it can make one additional slam attack at its highest base attack bonus."}],"description":"Unlike the standard, plodding zombie, a fast zombie moves with a supernatural quickness.","ecology":"","habitat_society":""},{"name":"Fetchling","cr":0.5,"xp":200,"race":"Fetchling","classes":[{"class":"rogue","level":1}],"alignment":"N","size":"Medium","type":"outsider","subtypes":["native"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex","hp":10,"hd":"1d8+2","hdvalue":1,"fort":2,"ref":5,"will":-1,"defensive_abilities":["shadow blending"],"resists":[{"type":"cold","value":5},{"type":"electricity","value":5}],"speed":[{"type":"land","speed":30}],"melee":"dagger +3 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"strength":13,"dexterity":17,"constitution":14,"intelligence":8,"wisdom":8,"charisma":14,"baseatk":0,"cmb":1,"cmd":14,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Appraise","value":3},{"skill":"Bluff","value":6},{"skill":"Diplomacy","value":6},{"skill":"Knowledge (local)","value":3},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":3},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":7}],"languages":["Common"],"sq":[{"type":"trapfinding","details":"+1"}],"environments":["any (Plane of Shadow)"],"organizations":["solitary","pair","guild (3-12)","enclave (13-30 plus 1-4 2nd-4th level rogue spies, 1-4 2nd-4th level sorcerers, and 1 3rd-6th level fighter/rogue leader)"],"treasure":"none","description_visual":"This gaunt man appears drained of color, like a person viewed at twilight or in a dark alley.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"description":"Fetchlings are descended from generations of humans trapped on the Plane of Shadow. Infused with the essence of that plane, they are more and less than human, and often serve as middlemen in planar trade and politics. Other than their yellow eyes, their flesh has no color-it is either stark white, midnight black, or a shade of gray. On the Material Plane, they conceal themselves with heavy clothing or dim light so they can work without prejudice. The name \"fetchling\" is a human word; their own name for their race is kayal, meaning \"shadow people.\"\n\nA fetchling stands 6 ft. tall, but is generally lithe and wiry of frame, weighing only 150 pounds. Fetchlings live as long as half-elves.","as_character":[{"description":"Fetchlings are defined by their class levels-they don't possess racial HD. They have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Charisma, -2 Wisdom: Fetchlings are quick and forceful, but often strange and easily distracted by errant thoughts."},{"type":"Darkvision","value":"Fetchlings see in the dark up to 60 ft."},{"type":"Low-Light Vision","value":"Fetchlings can see twice as far as humans in conditions of dim light."},{"type":"Skilled","value":"Fetchlings have a +2 racial bonus on Knowledge (planes) and Stealth checks."},{"type":"Shadow Blending","value":"See above."},{"type":"Shadowy Resistance","value":"Fetchlings have cold resistance 5 and electricity resistance 5."},{"type":"Spell-Like Abilities (Sp)","value":"A fetchling can use disguise self once per day as a spell-like ability. It can assume the form of any humanoid creature using this spell-like ability. When a fetchling reaches 9th level in any combination of classes, it gains shadow walk (self only) as a spell-like ability usable once per day, and at 13th level, it gains plane shift (self only, to the Plane of Shadow or the Material Plane only) usable once per day. A fetchling's caster level is equal to its total Hit Dice."},{"type":"Languages","value":"Fetchlings begin play speaking Common. A fetchling with a high Intelligence score can choose any of the following languages: Aklo, Aquan, Auran, Draconic, D'ziriak (understanding only, cannot speak), Ignan, Terran, and any regional human tongue."}]}],"ecology":"","habitat_society":"","gear":"chain shirt, dagger"},{"name":"Flaming Skull","cr":0.5,"xp":200,"alignment":"NE","size":"Tiny","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":1,"ref":1,"will":2,"immunities":["fire","undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"slam (1d2-1 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","strength":9,"dexterity":12,"wisdom":10,"charisma":13,"baseatk":0,"cmb":-3,"cmd":8,"cmd_special":"can't be tripped","skills":[{"skill":"Fly","value":9}],"environments":["any"],"organizations":["solitary","pair","patrol (3-6)"],"treasure":"none","description_visual":"This humanoid head floats silently and ominously, bits of flesh still hanging from its face and graying teeth clattering slightly as it bobs in the air.","group":"Beheaded","source":"AP 43","description":"Beheaded are floating skulls or severed heads whose bodies have long since abandoned them, either in the moment of death or long after. Reanimated via dark magic, these horrors are usually created as mindless sentinels for dungeons or lairs. Beheaded silently hover at about eye-level, often making them the last thing a casual wanderer or careless villager in an infested area ever sees. Creating Beheaded Spellcasters might create and employ beheaded in multiple ways. Animating Beheaded: A magic-user can create any form of beheaded from a severed head of the appropriate size or creature. The spellcaster must cast the spell animate dead using an onyx gem worth at least 100 gp, followed by the spell fly on the head to be animated. The creator can only create a number of Hit Dice of beheaded equal to the amount allowed by animate dead. Beheaded with the variant abilities below can also be created, though for the purposes of how many can be created, they are treated as if they had one additional Hit Die for each additional ability. Beheaded count against the number of Hit Dice of skeletons or zombies that can be created using animate dead and vise versa. Beheaded Familiars: Using the Improved Familiar feat, a spellcaster can gain an obedient severed head as a familiar. The character must be at least caster level 3rd to acquire the severed head. This creature is always neutral evil. Although any type of magic-user with the proper requisites can take a severed head as a familiar, necromancers and undead wizards employ them most frequently. Variant Beheaded The following are variant abilities that a beheaded might possess. These traits can be mixed and matched in any way and applied to any of the beheaded listed above. Each ability increases the CR of the beheaded by the listed amount. Belching (+1 CR): A belching beheaded gains the ability to spew raw energy from its mouth, giving it a ranged touch attack that does 1d6 damage of a specific type (acid, cold, electric, or fire) chosen at the time of the beheaded's animation. Burning (+1 CR): This beheaded is similar to the flaming skull; however, the fire not only surrounds the skull, but can pass on to those it attacks. The fire that consumes the head can be any color the animator chooses, though blue is one of the most common. A burning skull gains the burn (1d6) special ability when using its slam attack, where the Reflex save DC is 10 + 1/2 the burning skull's racial HD + the burning skull's Cha modifier. Grabbing (+0 CR): This type of beheaded has long tendrils of ragged hair. It gains the grab special ability when using its slam attack, and can attempt to grapple any creature of Medium size or smaller in this way Screaming (+0 CR): Once every 1d4 rounds, a screaming beheaded can open its jaw and emit a bone-chilling scream. All creatures within 30 ft. must make a Will save or be shaken for 1d4 rounds. The save DC is equal to 10 + 1/2 the screaming skull's racial HD + the screaming skull's Cha modifier. This is a sonic mind-affecting fear effect. Whether or not the save is successful, an affected creature is immune to the same beheaded's scream for 24 hours.","ecology":"","habitat_society":""},{"name":"Formian Worker","cr":0.5,"xp":200,"alignment":"LN","size":"Small","type":"monstrous humanoid","init":4,"init_special":"+8 with hive mind","senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"hive mind"}],"ac":12,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 natural, +1 size","hp":6,"hd":"1d10+1","hdvalue":1,"fort":1,"ref":2,"will":2,"resists":[{"type":"sonic","value":10}],"speed":[{"type":"land","speed":40},{"type":"burrow","speed":10}],"melee":"bite +3 (1d6+1)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":10,"constitution":13,"intelligence":10,"wisdom":10,"charisma":9,"baseatk":1,"cmb":1,"cmd":11,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Profession [miner])"}],"skills":[{"skill":"Climb","value":5},{"skill":"Knowledge (engineering)","value":4},{"skill":"Perception","value":4,"special":"+8 with hive mind"},{"skill":"Profession (miner)","value":7}],"languages":["Common","telepathy 60 ft."],"sq":[{"type":"able assistant"},{"type":"formian traits"},{"type":"peerless bearer"}],"environments":["temperate land","any underground","warm land"],"organizations":["solitary","work crew (6-12 plus 1 taskmaster)","band (3-15 plus 5-8 warriors and 1 taskmaster)."],"treasure":"incidental (occasionally a 10-50 gp gem embedded into a worker's carapace)","description_visual":"This small, centaurlike ant creature bears a huge, bulging sack on its armored back.","group":"Formian","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Able Assistant","kind":"Ex","details":"When a formian worker succeeds at an aid another check or attack roll that aids another hive mate within its telepathy range, it grants a +4 bonus on the skill check, on the attack roll, or to AC instead of the normal +2."},{"type":"Peerless Bearer","kind":"Ex","details":"Workers are able to bear remarkable burdens for their size. They have a +5 racial bonus to Strength when calculating the effects of encumbrance."}],"description":"These lowest-caste formians stand a little taller than a large dog, and their small mandibles are better equipped for slicing leaves and cutting fruit from the vine than carving into flesh. Regardless, many humanoids find the sight of these centaurlike ant creatures intimidating. Their iridescent chitin is nearly featureless, marked only by small scarring as they age and a series of markings on their chest. A few more accomplished formian workers bear small gems proudly glued to their carapace, tokens granted them by taskmasters for particularly impressive accomplishments. Formian workers are the backbone of the hive. They produce and harvest all food, perform all mining and tunneling, aid the taskmasters in the crafting of goods, and perform all other menial labor. Formian workers grow fast and learn quickly within the hive mind. Shortly after it leaves its larval stage, a formian is assigned to a senior worker who teaches it a trade, and by the end of the second year, a formian worker is a productive member of the hive. Workers live 20-30 years, and older workers are assigned lighter or more skilled work in order to give them capacity to train the young formian workers. Workers are hatched in large batches and given a clutch name, usually based on a well-regarded formian of the previous generation. Only when they leave their larval stage are workers given a unique number carved into their carapaces, which is used in place of an individual name. Workers parrot the taskmasters in many things; they denote accomplishments on their carapaces and even have duels (though duels among workers almost never involve death). Rarely, a particularly remarkable worker will be called out for special attention by their taskmaster, and these workers are presented to the queen and given a proper name of their own. Workers flee from combat unless they are ordered by a taskmaster or myrmarch to attack intruders. If a hive is invaded, formian workers might be used as diversions or to undermine or collapse tunnels on invading enemies. If forced into a direct fight, they usually spend most of their efforts assisting a warrior or myrmarch, though they make good use of mining picks or alchemist's fire if they are cornered.","ecology":"","habitat_society":""},{"name":"Gathlain","cr":0.5,"xp":200,"race":"Gathlain","classes":[{"class":"sorcerer","level":1}],"alignment":"CN","size":"Small","type":"fey","init":3,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +2 natural, +1 size","hp":7,"hd":"1d6+1","hdvalue":1,"fort":0,"ref":3,"will":1,"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"spear +2 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"entangle"},{"spell":"feather step"}]},{"frequency":"6/day","spells":[{"spell":"laughing touch"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":1,"spellsknown_concentration":1,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"color spray"},{"spell":"magic missile"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"ghost sound"},{"spell":"ray of frost"}]}],"strength":12,"dexterity":16,"constitution":11,"intelligence":10,"wisdom":8,"charisma":17,"baseatk":0,"cmb":0,"cmd":14,"feats":[{"feat":"Dodge"},{"feat":"Eschew Materials"}],"skills":[{"skill":"Fly","value":1},{"skill":"Knowledge (arcana)","value":4},{"skill":"Spellcraft","value":4}],"languages":["Common","Sylvan"],"sq":[{"type":"bloodline arcana","details":"+2 DC for compulsion spells"}],"environments":["temperate forests","temperate jungles"],"organizations":["solitary","flight (2-6)","grove (2-12)"],"treasure":"none","description_visual":"Wings composed of wood and vines grow out of the body of this lithesome fey.","source":"PFRPG Bestiary 4","description":"According to some fey ballads, gathlains were one of the first peoples awakened in the primal world of fey. They were created from the seeds of an enormous magical tree, with the tree's mistletoe grown into their flesh forming their strange wings. Mischievous and capricious, these creatures have discordant temperaments. They act purely to entertain themselves and sate their immense curiosity about the world around them. That very curiosity has caused many to migrate to the Material Plane and adventure there. These gathlains seek out and attempt to mingle with gnomes. However, gnomes often find gathlains too undisciplined, random, and foolish for their tastes.","as_character":[{"description":"Gathlains are defined by their class levels-they don't have racial Hit Dice. All gathlains have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, -2 Constitution, +2 Charisma: Gathlains are quick, with dynamic and engaging personalities, but are rather fragile."},{"type":"Small","value":"Gathlains are Small and gain a +1 size bonus on attack rolls, a -1 penalty on combat maneuver checks and to CMD, a +2 bonus on Fly checks, and a +4 size bonus on Stealth checks."},{"type":"Normal Speed","value":"Gathlains have a base speed of 30 ft. and a fly speed of 40 ft. (poor)."},{"type":"Low-Light Vision","value":"Gathlains can see twice as far as humans in dim light."},{"type":"Natural Armor","value":"Gathlains have a +1 natural armor bonus."},{"type":"Spell-Like Abilities","value":"1/day-entangle, feather step (caster level equals the gathlain's character level)."},{"type":"Languages","value":"Gathlains speak Common and Sylvan. A gathlain with a high Intelligence score can choose from the following languages: Draconic, Elven, Goblin, Halfling, and Orc."}]}],"ecology":"","habitat_society":"","gear":"spear"},{"name":"Ghoran","cr":0.5,"xp":200,"race":"Ghoran","classes":[{"class":"bard","level":1}],"alignment":"N","size":"Medium","type":"plant","init":1,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":12,"hd":"1d8+4","hdvalue":1,"fort":3,"ref":3,"will":3,"immunities":["plant traits"],"weaknesses":["delicious","light dependent"],"speed":[{"type":"land","speed":30}],"melee":"rapier +1 (1d6-1/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance","details":"7 rounds/day"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"detect poison"},{"spell":"goodberry"},{"spell":"purify food and drink"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":1,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"charm person"},{"spell":"disguise self"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"light"},{"spell":"mending"},{"spell":"message"}]}],"strength":8,"dexterity":13,"constitution":16,"intelligence":8,"wisdom":12,"charisma":17,"baseatk":0,"cmb":-1,"cmd":10,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Knowledge (history)","value":4},{"skill":"Knowledge (local)","value":4},{"skill":"Perception","value":5},{"skill":"Perform (sing)","value":7}],"languages":["Common","Sylvan"],"sq":[{"type":"bardic knowledge","details":"+1"},{"type":"ghorus seed"},{"type":"past-life knowledge"}],"environments":["any (Nex)"],"organizations":["solitary","pair","plot (3-12)"],"treasure":"none","description_visual":"This humanoid creature's taut green shell extends like a cowl from chin to brow, wreathing a face of brilliant flower petals.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Delicious","kind":"Ex","details":"Ghorans take a -2 penalty on Escape Artist and combat maneuver checks made to escape a grapple against any creature that has a bite attack with the grab ability."},{"type":"Ghorus Seed","kind":"Ex","details":"As a full-round action, a ghoran can expel its ghorus seed from an orifice in its abdomen. If planted in fertile ground and left undisturbed for 2d6 days, the seed grows into a healthy duplicate of the original ghoran, save that the duplicate may reallocate all of its skill ranks upon sprouting. Once a ghoran expels its seed, it gains 1 negative level, and it dies as soon as its duplicate sprouts. This duplicate replaces the previous ghoran character."},{"type":"Light Dependent","kind":"Ex","details":"Ghorans take 1d4 points of Constitution damage each day they go without exposure to sunlight."},{"type":"Past-Life Knowledge","kind":"Ex","details":"Ghorans remember memories encoded in their ghorus seed. They treat all Knowledge skills as class skills."}],"description":"When Geb's magic despoiled his kingdom, the archmage Nex enlisted the renegade druid Ghorus to create a form of plant life that could survive in the blighted wasteland and sustain his starving people. Eventually, the plants evolved sentience and ambulatory bodies mimicking the appearance of their human farmers and consumers.","as_character":[{"description":"Ghorans are defined by their class levels-they don't possess racial Hit Dice. They have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Con, +2 Cha, -2 Int: Ghorans are hardy and guileful, but process thoughts slowly."},{"type":"+2 Natural Armor","value":"Ghorans have tough, rugged skin."},{"type":"Plant","value":"Ghorans have the plant type."},{"type":"Natural Magic (2 RP)","value":"Ghorans with a Charisma score of 11 or higher gain the following spell-like abilities: 1/day-detect poison, goodberry (created berries bud from the ghoran's body), and purify food and drink. The caster level is equal to the ghoran's level. The DC for these spells is equal to 10 + the spell's level + the ghoran's Charisma bonus."},{"type":"Delicious (-1 RP)","value":"See above."},{"type":"Ghorus Seed (6 RP)","value":"See above."},{"type":"Light Dependent (-2 RP)","value":"See above."},{"type":"Past-Life Knowledge (2 RP)","value":"See above."},{"type":"Languages","value":"Ghorans begin play speaking Sylvan and Common. Ghorans with high Intelligence scores can choose any languages they want (except secret languages, such as Druidic)."}]}],"ecology":"","habitat_society":"","gear":"rapier"}];
